def _load_extra():
    import os
    f = os.path.join(os.path.dirname(os.path.abspath(__file__)), "pairs_extra.txt")
    for line in open(f, encoding="utf-8"):
        line = line.strip()
        if line:
            head, text = line.split("|", 1)
            a, b = head.split()
            OVERRIDES[k(a, b)] = text


_load_extra()
